+        for l in &lines {
+            // Tormach's guidelines: no % or $ fence. LinuxCNC reads an O
+            // word as a subroutine label, and the post numbers no blocks.
+            assert!(!l.contains('%') && !l.contains('$'), "{golden}: {l}");
+            assert!(!l.starts_with('O') && !l.starts_with('N'), "{golden}: {l}");
