+            "{golden}: blending tolerance on its own line"
+        );
+        // Z straight up, then G30, right before every tool change (the
+        // tool-change streams are pinned in the belt-range test below).
+        for (i, l) in lines.iter().enumerate() {
+            if l.ends_with(" M6") {
+                assert_eq!(
